struct RingBufferNode {
    std::atomic<bool> sequence_ready{false};
    Order order;
};

template <size_t Size>
class LockFreeRingBuffer {
    RingBufferNode buffer_[Size];
    std::atomic<uint64_t> head_{0};
    std::atomic<uint64_t> tail_{0};

public:
    bool push(const Order& order) {
        uint64_t current_tail = tail_.load(std::memory_order_relaxed);
        uint64_t current_head = head_.load(std::memory_order_acquire);

        if (current_tail - current_head >= Size) {
            return false; // Buffer full
        }

        buffer_[current_tail % Size].order = order;
        buffer_[current_tail % Size].sequence_ready.store(true, std::memory_order_release);
        tail_.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    bool pop(Order& order) {
        uint64_t current_head = head_.load(std::memory_order_relaxed);
        uint64_t current_tail = tail_.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Buffer empty
        }

        if (!buffer_[current_head % Size].sequence_ready.load(std::memory_order_acquire)) {
            return false; // Not yet written by producer
        }

        order = buffer_[current_head % Size].order;
        buffer_[current_head % Size].sequence_ready.store(false, std::memory_order_release);
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }
};
```

